labs.solution:
function reducer(state, action) {
  switch (action.type) {
    case "add":
      return { ...state, items: [...state.items, { id: action.id, done: false }] };
    case "toggle":
      if (!state.items.some((i) => i.id === action.id)) return state;
      return { ...state, items: state.items.map((i) => (i.id === action.id ? { ...i, done: !i.done } : i)) };
    case "clearDone": {
      const items = state.items.filter((i) => !i.done);
      return items.length === state.items.length ? state : { ...state, items };
    }
    default:
      return state;
  }
}

